#!/usr/bin/env python3
import json
from pathlib import Path


def main() -> int:
    manifest = json.loads(
        Path("/reference/klean-generation/generator-manifest.json").read_text()
    )
    kore = Path(
        "/reference/k-proof/verification-kompiled/definition.kore"
    ).read_text()
    for parameter in manifest["target"]["parameters"]:
        symbol = parameter["kore_symbol"]
        print(
            json.dumps(
                {
                    "name": parameter["name"],
                    "kore_symbol": symbol,
                    "definition_kore_occurrences": kore.count(symbol),
                    "source_rule_ids": parameter["source_rule_ids"],
                },
                sort_keys=True,
            )
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

